package netproxy

import (
	"net/url"
	"os"
	"slices"
	"strings"
	"sync"
)

// ForwardedVariables are the variables a container receives, in this order,
// each name followed by its other casing. ALL_PROXY and FTP_PROXY are not read.
var ForwardedVariables = []string{
	"HTTP_PROXY", "http_proxy",
	"HTTPS_PROXY", "https_proxy",
	"NO_PROXY", "no_proxy",
}

// redacted stands for a proxy value that could not be parsed, so it has no
// display form.
const redacted = "[redacted]"

// forwardPair is one variable in both casings, with the value they both carry.
type forwardPair struct {
	names [2]string
	value string
	// read is the name the value was read from, with the case it had.
	read string
}

// Forward is a snapshot of the proxy variables as a child process must receive
// them. It holds raw values, credentials included, and never prints them: String
// and GoString show the display form. A Forward kept in an unexported field is
// walked by fmt, which cannot call String there, so the values sit behind a
// function: fmt prints an address for it, with every verb (a pointer to a struct
// would be followed by %s). The zero value forwards nothing.
type Forward struct {
	get func() []forwardPair
}

// pairs returns the variables held, none for the zero value.
func (f Forward) pairs() []forwardPair {
	if f.get == nil {
		return nil
	}
	return f.get()
}

// containerForward reads the environment once, like http.ProxyFromEnvironment.
var containerForward = sync.OnceValue(func() Forward {
	return ForwardFromLookup(os.LookupEnv)
})

// ContainerForward is the proxy environment of this process, read once.
func ContainerForward() Forward { return containerForward() }

// ForwardFromLookup reads the variables through lookup. For each of HTTP, HTTPS
// and NO, the first non-empty value of the upper case name then the lower case
// name is given to both names. The value is not validated.
func ForwardFromLookup(lookup func(string) (string, bool)) Forward {
	getenv := func(name string) string {
		v, _ := lookup(name)
		return v
	}
	var pairs []forwardPair
	for i := 0; i < len(ForwardedVariables); i += 2 {
		names := [2]string{ForwardedVariables[i], ForwardedVariables[i+1]}
		if read, value := firstNonEmpty(names, getenv); read != "" {
			pairs = append(pairs, forwardPair{names: names, value: value, read: read})
		}
	}
	if len(pairs) == 0 {
		return Forward{}
	}
	return Forward{get: func() []forwardPair { return pairs }}
}

// Empty reports whether there is nothing to forward.
func (f Forward) Empty() bool { return len(f.pairs()) == 0 }

// Names lists the variables to pass, in ForwardedVariables order.
func (f Forward) Names() []string {
	var names []string
	for _, p := range f.pairs() {
		names = append(names, p.names[:]...)
	}
	return names
}

// Environ returns base without any of the six forwarded names, followed by
// NAME=value for every name to forward. base is not modified; when there is
// nothing to forward it is returned as is.
func (f Forward) Environ(base []string) []string {
	if f.Empty() {
		return base
	}
	env := make([]string, 0, len(base)+len(f.pairs())*2)
	for _, kv := range base {
		name, _, _ := strings.Cut(kv, "=")
		if !slices.Contains(ForwardedVariables, name) {
			env = append(env, kv)
		}
	}
	for _, p := range f.pairs() {
		for _, name := range p.names {
			env = append(env, name+"="+p.value)
		}
	}
	return env
}

// Loopback reports whether a proxy the container would use is on this machine,
// where it cannot be reached from inside the container. The HTTPS pair is tried
// before the HTTP pair and the first loopback value wins. variable is the name
// that was read and display carries no credential.
func (f Forward) Loopback() (variable, display string, ok bool) {
	for _, upper := range []string{"HTTPS_PROXY", "HTTP_PROXY"} {
		for _, p := range f.pairs() {
			if p.names[0] != upper {
				continue
			}
			if u, usable := parseProxyValue(p.value); usable && isLoopbackHost(u.Hostname()) {
				return p.read, Display(u), true
			}
		}
	}
	return "", "", false
}

// Redact removes every credential held by f from s: a raw proxy value that
// carries credentials becomes its display form (or [redacted] when it is
// unusable), and its userinfo and its password disappear, as written in the
// value, as Go escapes them and decoded. A value with no credentials is left as
// the tool wrote it, so a diagnostic still names what was dialed. For an
// unusable value holding "@", everything before the last "@" is taken for a
// userinfo. A secret shorter than 4 bytes is only removed in the full value and
// in user:password@, since replacing it anywhere would damage the text; a bare
// user name shorter than 4 bytes is not removed at all.
func (f Forward) Redact(s string) string { return f.Redactor()(s) }

// Redactor is Redact with the replacements prepared once, for a caller that
// redacts many lines.
func (f Forward) Redactor() func(string) string {
	var r redaction
	for _, p := range f.pairs() {
		if p.names[0] != "NO_PROXY" {
			r.addValue(p.value)
		}
	}
	return r.replacer()
}

// redaction collects what Redact removes. strings.Replacer tries its arguments
// in order at each position, so replacer lists the longest kinds first.
type redaction struct {
	values    [][2]string // raw value and what stands for it
	userinfos []string    // removed together with their "@"
	secrets   []string    // replaced wherever they appear
}

// addValue records one raw proxy value and the credentials it holds. A value
// with none is not recorded: replacing it by its display form would only distort
// the text around it.
func (r *redaction) addValue(value string) {
	display := redacted
	u, usable := parseProxyValue(value)
	hasCredentials := !usable && strings.Contains(value, "@")
	if usable {
		display = Display(u)
		if u.User != nil {
			hasCredentials = true
			r.addUserinfo(u.User.String())
		}
	}
	if !hasCredentials {
		return
	}
	r.values = append(r.values, [2]string{value, display})
	rest := value[len(explicitScheme.FindString(value)):]
	if usable {
		// The authority ends at the first "/", "?" or "#".
		if end := strings.IndexAny(rest, "/?#"); end >= 0 {
			rest = rest[:end]
		}
	}
	// Written out, whatever the escaping: up to the last "@".
	if at := strings.LastIndex(rest, "@"); at >= 0 {
		r.addUserinfo(rest[:at])
	}
}

// addUserinfo records a userinfo as written, user[:password], and its decoded
// form. The secret is the password, or the user name when the password is
// absent or empty.
func (r *redaction) addUserinfo(info string) {
	user, password, _ := strings.Cut(info, ":")
	secret := password
	if secret == "" {
		secret = user
	}
	for _, v := range unescapedToo(info) {
		// A bare short name would match the local part of an address.
		if v != "" && (strings.Contains(v, ":") || len(v) >= 4) {
			r.userinfos = append(r.userinfos, v)
		}
	}
	for _, v := range unescapedToo(secret) {
		if len(v) >= 4 {
			r.secrets = append(r.secrets, v)
		}
	}
}

// unescapedToo returns s and, when it differs and decodes, its percent-decoded form.
func unescapedToo(s string) []string {
	if d, err := url.PathUnescape(s); err == nil && d != s {
		return []string{s, d}
	}
	return []string{s}
}

// replacer builds the replacements once and returns the function applying them.
func (r *redaction) replacer() func(string) string {
	var olds []string
	byLength := func(a, b string) int { return len(b) - len(a) }
	slices.SortStableFunc(r.values, func(a, b [2]string) int { return byLength(a[0], b[0]) })
	for _, v := range r.values {
		olds = append(olds, v[0], v[1])
	}
	slices.SortStableFunc(r.userinfos, byLength)
	for _, info := range slices.Compact(r.userinfos) {
		olds = append(olds, info+"@", "")
	}
	slices.SortStableFunc(r.secrets, byLength)
	for _, secret := range slices.Compact(r.secrets) {
		olds = append(olds, secret, redacted)
	}
	if len(olds) == 0 {
		return func(s string) string { return s }
	}
	return strings.NewReplacer(olds...).Replace
}

// String shows the variables with the proxies in display form, never raw. A
// NO_PROXY value with a non-printable character is not shown, since it ends up
// on a terminal.
func (f Forward) String() string {
	if f.Empty() {
		return "no proxy variables"
	}
	parts := make([]string, 0, len(f.pairs()))
	for _, p := range f.pairs() {
		shown := redacted
		if p.names[0] == "NO_PROXY" {
			if isPrintable(p.value) {
				shown = p.value
			}
		} else if u, ok := parseProxyValue(p.value); ok {
			shown = Display(u)
		}
		parts = append(parts, p.names[0]+"="+shown)
	}
	return strings.Join(parts, " ")
}

// GoString is String, so %#v shows no raw value either.
func (f Forward) GoString() string { return f.String() }
package netproxy

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"sync"
	"testing"
)

// DEVDESK-583: the guard that keeps every container launch of the scanners on
// containerRun.cmd (internal/scan/container_run.go), the one place that forwards
// the proxy variables into the container. Like the HTTP guard it parses the
// production sources of the whole module (go/ast, no type information) and
// reports the two ways code has found to build a `docker|podman run`:
//
//	C1  a []string literal whose first element is "run"
//	C2  a call with the literal "run" as argument 0 or 1 and at least one
//	    argument after it: exec.Command(bin, "run", img), dockerCombined("run", ...)
//
// A label such as cmdLabel("run") has no argument after "run" and is not
// reported. What the guard cannot see (a "run" assembled at run time, a
// "container run" spelling) is documented in docs/architecture/network.md.

const (
	ruleContainerSlice = "C1"
	ruleContainerCall  = "C2"

	// containerRunFile and containerRunFunc are the one site allowed to build a
	// run. It is hard-coded here and not an exception: it is the entry point.
	containerRunFile = "internal/scan/container_run.go"
	containerRunFunc = "containerRun.cmd"
)

var containerRules = []string{ruleContainerSlice, ruleContainerCall}

// containerExceptions is the whole list. Each entry is also named in the
// "Container scanners" section of docs/architecture/network.md
// (TestNetworkDocListsEveryContainerException).
var containerExceptions = []exception{
	{
		File: "internal/docker/launch.go", Func: "buildLaunchArgs", Rule: ruleContainerSlice,
		Why:   "the user's own container, configured in the launch form; not a scanner (outside DEVDESK-583)",
		Until: "permanent",
	},
	{
		File: "internal/docker/launch.go", Func: "VerifyEntrypoint", Rule: ruleContainerCall,
		Why:   "runs only `command -v`, nothing to forward",
		Until: "permanent",
	},
}

// isRunLiteral reports whether e is the string literal "run" (or `run`).
func isRunLiteral(e ast.Expr) bool {
	lit, ok := e.(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return false
	}
	s, err := strconv.Unquote(lit.Value)
	return err == nil && s == "run"
}

// isStringSlice reports whether t is the type expression []string.
func isStringSlice(t ast.Expr) bool {
	at, ok := t.(*ast.ArrayType)
	if !ok || at.Len != nil {
		return false
	}
	id, ok := at.Elt.(*ast.Ident)
	return ok && id.Name == "string"
}

// scanContainerSource parses src as the file name (a slash path from the module
// root) and returns its C1 and C2 violations ordered by line, then rule.
func scanContainerSource(name string, src []byte) ([]violation, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	var out []violation
	add := func(pos token.Pos, rule, fn string) {
		out = append(out, violation{File: name, Line: fset.Position(pos).Line, Rule: rule, Func: fn})
	}
	inspect := func(node ast.Node, fn string) {
		ast.Inspect(node, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.CompositeLit:
				if n.Type != nil && isStringSlice(n.Type) && len(n.Elts) > 0 && isRunLiteral(n.Elts[0]) {
					add(n.Pos(), ruleContainerSlice, fn)
				}
			case *ast.CallExpr:
				for i := 0; i < 2 && i+1 < len(n.Args); i++ {
					if isRunLiteral(n.Args[i]) {
						add(n.Pos(), ruleContainerCall, fn)
						break
					}
				}
			}
			return true
		})
	}
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			inspect(d, funcName(d))
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch sp := spec.(type) {
				case *ast.ValueSpec:
					inspect(sp, sp.Names[0].Name)
				case *ast.TypeSpec:
					inspect(sp, sp.Name.Name)
				}
			}
		}
	}
	slices.SortStableFunc(out, func(a, b violation) int {
		if a.Line != b.Line {
			return a.Line - b.Line
		}
		return strings.Compare(a.Rule, b.Rule)
	})
	return out, nil
}

// scanContainerTree scans every non-test .go file under root, with the same
// exclusions as the HTTP guard (guardExcludedDirs, matched on the names below
// root) but internal/netproxy included: nothing there launches a container
// either. It also returns the number of files read.
func scanContainerTree(root string) ([]violation, int, error) {
	var all []violation
	files := 0
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if d.IsDir() {
			if rel != "." && slices.Contains(guardExcludedDirs, d.Name()) {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
			return nil
		}
		src, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		vs, err := scanContainerSource(rel, src)
		if err != nil {
			return err
		}
		files++
		all = append(all, vs...)
		return nil
	})
	return all, files, err
}

var (
	containerOnce       sync.Once
	containerViolations []violation
	containerFiles      int
	containerErr        error
)

// scanContainerRepo scans the module that holds this package, once per test
// process, and returns its root.
func scanContainerRepo(t *testing.T) (string, []violation) {
	t.Helper()
	root, _ := scanRepo(t)
	containerOnce.Do(func() {
		containerViolations, containerFiles, containerErr = scanContainerTree(root)
	})
	if containerErr != nil {
		t.Fatalf("scanning the module for container launches: %v", containerErr)
	}
	// A walk that reads almost nothing would pass for the wrong reason.
	if containerFiles < 50 {
		t.Fatalf("the container guard read %d files under %s, want the whole module", containerFiles, root)
	}
	return root, containerViolations
}

// isContainerEntryPoint reports whether v is in the one function allowed to
// build a run.
func isContainerEntryPoint(v violation) bool {
	return v.File == containerRunFile && v.Func == containerRunFunc
}

// No scanner launches a container but through containerRun.cmd, which forwards
// the proxy variables; the listed exceptions are not scanners.
func TestContainerGuardNoLaunchBypassesTheProxyForward(t *testing.T) {
	_, vs := scanContainerRepo(t)
	for _, v := range vs {
		if isContainerEntryPoint(v) {
			continue
		}
		if slices.ContainsFunc(containerExceptions, func(e exception) bool { return e.covers(v) }) {
			continue
		}
		t.Errorf("%s: builds a container run by hand; build it with containerRun in %s so the proxy variables are forwarded (containerRun.cmd), or add a reasoned exception to containerExceptions and to docs/architecture/network.md", v, containerRunFile)
	}
}

// An exception that matches nothing is stale, and so is an entry point that no
// longer builds the run: the guard would pass with nothing left to guard.
func TestContainerGuardEveryExceptionStillMatches(t *testing.T) {
	_, vs := scanContainerRepo(t)
	if !slices.ContainsFunc(vs, isContainerEntryPoint) {
		t.Errorf("%s no longer builds a run in %s; the entry point moved, update containerRunFile/containerRunFunc and the doc", containerRunFunc, containerRunFile)
	}
	seen := map[exception]bool{}
	for _, e := range containerExceptions {
		key := exception{File: e.File, Func: e.Func, Rule: e.Rule}
		if seen[key] {
			t.Errorf("exception %s %s %s is listed twice", e.File, e.Func, e.Rule)
		}
		seen[key] = true
		if !slices.Contains(containerRules, e.Rule) {
			t.Errorf("exception %s %s: rule %q is not one of %v", e.File, e.Func, e.Rule, containerRules)
		}
		if strings.TrimSpace(e.Why) == "" || strings.TrimSpace(e.Until) == "" {
			t.Errorf("exception %s %s %s needs a reason and an end (\"permanent\" or a story)", e.File, e.Func, e.Rule)
		}
		if !slices.ContainsFunc(vs, e.covers) {
			t.Errorf("stale exception: %s %s %s matches no container launch any more; remove it from containerExceptions and docs/architecture/network.md", e.File, e.Func, e.Rule)
		}
	}
}

func TestContainerGuardDetectors(t *testing.T) {
	cases := []guardCase{
		{
			name: "a literal slice starting with run",
			src: `package p
func a() []string { return []string{"run", "--rm"} }
`,
			want: []string{"x.go:2: C1 (a)"},
		},
		{
			name: "a one-element slice with run",
			src: `package p
func a(x []string) []string { return append([]string{"run"}, x...) }
`,
			want: []string{"x.go:2: C1 (a)"},
		},
		{
			name: "a slice with run at package scope",
			src: `package p
var base = []string{"run", "-d"}
`,
			want: []string{"x.go:2: C1 (base)"},
		},
		{
			name: "a slice with run in a closure belongs to its declaration",
			src: `package p
type T struct{}
func (t *T) m() func() []string {
	return func() []string { return []string{"run", "x"} }
}
`,
			want: []string{"x.go:4: C1 (T.m)"},
		},
		{
			name: "run at argument 1 of a call",
			src: `package p
import "os/exec"
func a(b, i string) { _ = exec.Command(b, "run", i) }
`,
			want: []string{"x.go:3: C2 (a)"},
		},
		{
			name: "run at argument 0 of a call",
			src: `package p
func f(a ...string) {}
func a() { f("run", "--rm") }
`,
			want: []string{"x.go:3: C2 (a)"},
		},
		{
			name: "run followed by a spread",
			src: `package p
func f(a string, b ...string) {}
func a(x []string) { f("run", x...) }
`,
			want: []string{"x.go:3: C2 (a)"},
		},
		{
			name: "a label with run alone",
			src: `package p
func cmdLabel(s string) string { return s }
func a() string { return cmdLabel("run") }
`,
		},
		{
			name: "run last, with nothing after it",
			src: `package p
func f(a, b string) {}
func a() { f("x", "run") }
`,
		},
		{
			name: "run at argument 2 is not a launch",
			src: `package p
func f(a, b, c, d string) {}
func a() { f("x", "y", "run", "z") }
`,
		},
		{
			name: "run after another element in a slice",
			src: `package p
func a() []string { return []string{"--rm", "run"} }
`,
		},
		{
			name: "a slice of another type",
			src: `package p
func a() []any { return []any{"run", "x"} }
`,
		},
		{
			name: "a constant is not a launch",
			src: `package p
const s = "run"
var t = "run"
`,
		},
		{
			name: "a longer word is not run",
			src: `package p
func f(a, b, c string) {}
func a() { f("x", "runner", "y"); _ = []string{"running"} }
`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			vs, err := scanContainerSource("x.go", []byte(tc.src))
			if err != nil {
				t.Fatalf("the synthetic source does not parse: %v", err)
			}
			got := make([]string, len(vs))
			for i, v := range vs {
				got[i] = v.String()
			}
			if !slices.Equal(got, tc.want) {
				t.Errorf("report =\n  %s\nwant\n  %s", strings.Join(got, "\n  "), strings.Join(tc.want, "\n  "))
			}
		})
	}

	// Every rule has at least one case that triggers it, so a rule cannot be
	// dropped from the detector while the table stays green.
	t.Run("every rule is exercised", func(t *testing.T) {
		for _, r := range containerRules {
			if !slices.ContainsFunc(cases, func(tc guardCase) bool {
				return slices.ContainsFunc(tc.want, func(w string) bool { return strings.Contains(w, ": "+r+" (") })
			}) {
				t.Errorf("no detector case triggers %s", r)
			}
		}
	})
}

// The walk: the excluded directory names apply below the root only (a root under
// .worktrees is still scanned), test files are skipped, and, unlike the HTTP
// guard, internal/netproxy is read.
func TestContainerGuardWalk(t *testing.T) {
	root := filepath.Join(t.TempDir(), ".worktrees", "feat", "wt")
	bad := "package p\nfunc a() []string { return []string{\"run\"} }\n"
	files := map[string]string{
		"go.mod":                     "module example.com/m\n",
		"main.go":                    bad,
		"pkg/deep/ok.go":             bad,
		"pkg/clean.go":               "package p\n",
		"pkg/thing_test.go":          bad,
		"internal/netproxy/own.go":   bad,
		".worktrees/other/w.go":      bad,
		"pkg/.worktrees/nested/w.go": bad,
		".git/hooks/h.go":            bad,
		"vendor/v/v.go":              bad,
		"pkg/testdata/t.go":          bad,
		"docs-site/node/d.go":        bad,
		"web/node_modules/n/n.go":    bad,
		"README.md":                  "not go",
	}
	for name, content := range files {
		p := filepath.Join(root, filepath.FromSlash(name))
